    @inline(__always)
    private func checkSumsOfShuffledQuadAbsoluteDifferencesFromUInt8UncheckedConstantImmediates(
        _ i3: Int,
        _ i2: Int,
        _ i1: Int,
        _ i0: Int
    ) {
        let mismatches = Mismatches(
            "sumsOfShuffledQuadAbsoluteDifferencesFromUInt8 unchecked with i3 \(i3), i2 \(i2), i1 \(i1), i0 \(i0)"
        )
        let aInputs = Inputs.conversions(SIMDUInt8.Vector.self, seed: 0x804F_4C64_BBA5_831D)
        let bInputs = Inputs.conversions(SIMDUInt8.Vector.self, seed: 0x804F_4B64_BBA5_816A)
        for (a, b) in everyPair(aInputs, bInputs) {
            mismatches.check(
                unsafe H.sumsOfShuffledQuadAbsoluteDifferences(a, b, unchecked: i3, i2, i1, i0),
                H.Vector(
                    raw: HighwayReference.sumsOfShuffledQuadAbsoluteDifferencesU8ToU16(
                        a.raw,
                        b.raw,
                        Int32(truncatingIfNeeded: i3),
                        Int32(truncatingIfNeeded: i2),
                        Int32(truncatingIfNeeded: i1),
                        Int32(truncatingIfNeeded: i0)
                    )
                ),
                "a: \(describe(a)), b: \(describe(b))"
            )
        }
        mismatches.record()
    }

    @Test func sumsOfShuffledQuadAbsoluteDifferencesFromUInt8UncheckedConstantImmediates0000() {
        checkSumsOfShuffledQuadAbsoluteDifferencesFromUInt8UncheckedConstantImmediates(0, 0, 0, 0)
